mapper.select:
 WHERE s.tenant_id = #{tenantId}
AND s.outbound_id = #{outboundId}
ORDER BY s.reported_at DESC, s.short_pick_id

mapper.update:
UPDATE wms_outbound_allocation SET short_quantity = short_quantity + #{quantity}
WHERE tenant_id = #{tenantId} AND allocation_id = #{allocationId}
  AND planned_quantity - picked_quantity - short_quantity - cancelled_quantity >= #{quantity}

UPDATE wms_batch_location_balance
SET reserved_quantity = reserved_quantity - #{quantity}, review_quantity = review_quantity + #{quantity}
WHERE tenant_id = #{tenantId} AND batch_no = #{a.batchNo} AND location_id = #{a.locationId}
  AND reserved_quantity - picked_quantity >= #{quantity}

UPDATE wms_short_pick SET replacement_request_id = #{requestId}, replacement_allocation_id = #{allocationId},
    replaced_by = #{operatorId}, replaced_at = #{at}
WHERE tenant_id = #{tenantId} AND short_pick_id = #{id}

UPDATE wms_short_pick SET found_quantity = #{found}, missing_quantity = #{missing}, count_remark = #{remark},
    counted_by = #{operatorId}, counted_at = #{at}
WHERE tenant_id = #{tenantId} AND short_pick_id = #{id}

UPDATE wms_batch_location_balance SET quantity = quantity - #{c.missingQuantity},
    review_quantity = review_quantity - #{c.shortQuantity}
WHERE tenant_id = #{tenantId} AND batch_no = #{c.batchNo} AND location_id = #{c.locationId}
  AND review_quantity >= #{c.shortQuantity} AND quantity - reserved_quantity >= #{c.shortQuantity}
